// One-off generator: builds client/src/i18n/locales/{lang}.json from
// mobile's existing translations (reused verbatim for overlapping domain
// vocabulary) plus new web-only keys (translated here for all 10 languages).
// Run with: node scripts/gen-i18n.mjs   (from client/)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..', '..'); // repo root
const MOBILE_LOCALES = path.join(ROOT, 'mobile', 'src', 'i18n', 'locales');
const OUT_DIR = path.join(__dirname, '..', 'src', 'i18n', 'locales');

const LANGS = ['en', 'fr', 'sw', 'rw', 'es', 'pt', 'de', 'ar', 'zh', 'hi'];

const M = {};
for (const l of LANGS) {
  M[l] = JSON.parse(fs.readFileSync(path.join(MOBILE_LOCALES, `${l}.json`), 'utf8'));
}

// positional helper: en, fr, sw, rw, es, pt, de, ar, zh, hi
function o(en, fr, sw, rw, es, pt, de, ar, zh, hi) {
  return { en, fr, sw, rw, es, pt, de, ar, zh, hi };
}

// "e.g." in each language, used to build example placeholders like "e.g. COW-001"
const EG = { en: 'e.g.', fr: 'ex. :', sw: 'mf.', rw: 'urugero:', es: 'ej.', pt: 'ex.:', de: 'z. B.', ar: 'مثال:', zh: '例如：', hi: 'उदा.' };
function eg(lang, example) {
  if (lang === 'zh') return `${EG[lang]}${example}`;
  return `${EG[lang]} ${example}`;
}
function egObj(example) {
  const r = {};
  for (const l of LANGS) r[l] = eg(l, example);
  return r;
}

function setDeep(obj, dotPath, value) {
  const parts = dotPath.split('.');
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    cur[parts[i]] = cur[parts[i]] || {};
    cur = cur[parts[i]];
  }
  cur[parts[parts.length - 1]] = value;
}

const out = {};
for (const l of LANGS) out[l] = {};

// ---- 1. Reuse verbatim from mobile (identical domain vocabulary) ----
const REUSE_NAMESPACES = ['common', 'nav', 'auth', 'geo', 'confirmDialogs', 'records', 'tables', 'enums', 'reports'];
for (const l of LANGS) {
  for (const ns of REUSE_NAMESPACES) {
    out[l][ns] = JSON.parse(JSON.stringify(M[l][ns]));
  }
}

