// ---- 3. Apply all ENTRIES into `out[lang]` at their dot-paths ----
for (const [dotPath, translations] of Object.entries(ENTRIES)) {
  for (const l of LANGS) {
    if (!(l in translations)) throw new Error(`Missing language "${l}" for key "${dotPath}"`);
    setDeep(out[l], dotPath, translations[l]);
  }
}

// ---- 4. Write locale files ----
if (!fs.existsSync(OUT_DIR)) fs.mkdirSync(OUT_DIR, { recursive: true });
for (const l of LANGS) {
  const filePath = path.join(OUT_DIR, `${l}.json`);
  fs.writeFileSync(filePath, JSON.stringify(out[l], null, 2) + '\n', 'utf8');
}
console.log(`Wrote ${LANGS.length} locale files to ${OUT_DIR}`);
console.log('New keys added:', Object.keys(ENTRIES).length);

// ---- 5. Verify key-set parity across all 10 locale files ----
function flattenKeys(obj, prefix = '') {
  let keys = [];
  for (const k of Object.keys(obj)) {
    const full = prefix ? `${prefix}.${k}` : k;
    if (obj[k] && typeof obj[k] === 'object' && !Array.isArray(obj[k])) {
      keys = keys.concat(flattenKeys(obj[k], full));
    } else {
      keys.push(full);
    }
  }
  return keys;
}

const keySets = {};
for (const l of LANGS) keySets[l] = flattenKeys(out[l]).sort();

const referenceKeys = keySets.en;
let allMatch = true;
for (const l of LANGS) {
  if (l === 'en') continue;
  const a = new Set(referenceKeys);
  const b = new Set(keySets[l]);
  const missing = referenceKeys.filter((k) => !b.has(k));
  const extra = keySets[l].filter((k) => !a.has(k));
  if (missing.length || extra.length) {
    allMatch = false;
    console.error(`Key mismatch in ${l}.json:`);
    if (missing.length) console.error('  missing:', missing);
    if (extra.length) console.error('  extra:', extra);
  }
}
console.log(allMatch ? 'PARITY OK: all 10 locale files have identical key sets.' : 'PARITY FAILED');
console.log('Total keys per file:', referenceKeys.length);
